<script setup>
import { computed, reactive, ref } from "vue"; import { Save } from "@lucide/vue"; import AdminLayout from "../components/admin/AdminLayout.vue"; import DataTable from "../components/DataTable.vue"; import AppModal from "../components/AppModal.vue"; import AsyncButton from "../components/AsyncButton.vue"; import FormField from "../components/FormField.vue"; import TextInput from "../components/TextInput.vue"; import TextareaInput from "../components/TextareaInput.vue"; import SelectInput from "../components/SelectInput.vue"; import TableActionButton from "../components/TableActionButton.vue"; import { useServerTable } from "../services/serverTable"; import { apiFetch } from "../services/api"; import { useFormErrors } from "../services/formErrors"; import { toast } from "../services/toast"; import { t } from "../services/i18n";
const {items,loading,pagination,load,updateItem}=useServerTable({endpoint:"/api/v1/admin/inventory",collectionKey:"inventory"}); const columns=computed(()=>[{key:"name",label:t("products.name")},{key:"sku",label:t("products.sku")},{key:"current_stock",label:t("stock.current")},{key:"action",label:t("common.action"),sortable:false}]);
const open=ref(false),modalLoading=ref(false),saving=ref(false),product=ref(null),formElement=ref(null); const errors=useFormErrors(); const form=reactive({movement_type:"",quantity:1,note:""}); const outTypes=["adjustment_out","damaged","lost","internal_use"];
const estimated=computed(()=>product.value ? product.value.current_stock+(outTypes.includes(form.movement_type)?-Math.abs(Number(form.quantity)||0):Math.abs(Number(form.quantity)||0)) : 0);
async function show(item){open.value=true;modalLoading.value=true;Object.assign(form,{movement_type:"",quantity:1,note:""});try{product.value=(await apiFetch(`/api/v1/admin/stock_movements/${item.id}/adjustment`)).product}catch(e){toast.error(e.message);open.value=false}finally{modalLoading.value=false}}
function close(){if(saving.value||modalLoading.value)return;open.value=false;product.value=null;errors.clearErrors()}
async function submit(){const valid=await errors.validate({movement_type:()=>form.movement_type?"":t("validation.required"),quantity:()=>Number(form.quantity)>0?"":t("validation.required"),note:()=>form.note.trim()?"":t("validation.required")},formElement.value);if(!valid){toast.warning(t("validation.fix_fields"));return} saving.value=true;try{const r=await apiFetch("/api/v1/admin/stock_movements",{method:"POST",body:JSON.stringify({...form,product_id:product.value.id,quantity:Number(form.quantity)})});updateItem(product.value.id,{current_stock:r.stock_movement.stock_after});toast.success(t("stock.saved",{name:product.value.name}));open.value=false;product.value=null}catch(e){await errors.applyApiError(e,formElement.value);toast.error(e.message)}finally{saving.value=false}}
</script>
<template><AdminLayout><div class="mx-auto max-w-[1536px]"><div class="mb-6"><h1 class="text-2xl font-semibold dark:text-white">{{t('stock.adjustment_title')}}</h1><p class="mt-1 text-sm text-gray-500">{{t('stock.adjustment_subtitle')}}</p></div><DataTable :items="items" :columns="columns" :loading="loading" :empty-text="t('stock.empty')" server-mode :total="pagination.total" @request="load"><template #cell-name="{item}"><strong>{{item.name}}</strong></template><template #cell-current_stock="{item}">{{item.current_stock}} {{item.unit}}</template><template #cell-action="{item}"><TableActionButton action="edit" :label="t('stock.adjust')" :accessible-label="`${t('stock.adjust')} ${item.name}`" @click="show(item)"/></template></DataTable></div><AppModal :open="open" :title="product ? `${t('stock.adjust')} ${product.name}` : t('stock.adjustment_title')" :loading="modalLoading" :close-disabled="saving" size="lg" @close="close"><form v-if="product" ref="formElement" id="stock-form" class="space-y-5" @submit.prevent="submit"><p class="rounded-xl bg-gray-50 p-4 text-sm">{{t('stock.current')}}: <strong>{{product.current_stock}} {{product.unit}}</strong></p><FormField :label="t('stock.type')" :error="errors.errorFor('movement_type')"><SelectInput v-model="form.movement_type" name="movement_type"><option value="">{{t('stock.select_type')}}</option><option value="adjustment_in">{{t('stock.increase')}}</option><option value="adjustment_out">{{t('stock.decrease')}}</option><option value="damaged">{{t('stock.damaged')}}</option><option value="lost">{{t('stock.lost')}}</option><option value="internal_use">{{t('stock.internal_use')}}</option></SelectInput></FormField><FormField :label="t('stock.quantity')" :error="errors.errorFor('quantity')"><TextInput v-model="form.quantity" name="quantity" type="number" min="1"/></FormField><FormField :label="t('stock.note')" :error="errors.errorFor('note')"><TextareaInput v-model="form.note" name="note" rows="3"/></FormField><p :class="estimated<0?'text-error-600':'text-gray-500'" class="text-sm">{{t('stock.estimated_after',{count:estimated})}}</p></form><template #footer><button class="rounded-lg border px-4 py-2.5" @click="close">{{t('common.cancel')}}</button><AsyncButton form="stock-form" type="submit" :loading="saving" :disabled="estimated<0" :loading-text="t('common.saving')" class="rounded-lg bg-brand-500 px-5 py-2.5 text-white"><Save :size="16"/>{{t('common.save')}}</AsyncButton></template></AppModal></AdminLayout></template>
